-- VPS import: SVN-Customer_STB_Location_Report.xlsx (900 unique 15-digit STBs).
-- Select the application database; back up and pause STB edits/imports/assignments.
-- Run the WHOLE file in one session. No customer/issue/payment records are changed.
-- Spreadsheet provides numbers only. HD box type confirmed by the user.
-- NEW is the master stock-type default, not a condition verified by the workbook.
-- New entries have zero prices, no MSO/employee, and NOT_AVAILABLE status.
-- Existing masters, including inactive masters, are skipped; no duplicates inserted.
SET @import_stb_box_type = 'HD';
DROP TEMPORARY TABLE IF EXISTS tmp_svn_stb_import;
CREATE TEMPORARY TABLE tmp_svn_stb_import (
 stb_number VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci PRIMARY KEY
) ENGINE=InnoDB;

-- Guard before any permanent writes; no nested result sets (phpMyAdmin compatible).
DROP PROCEDURE IF EXISTS tcv_import_svn_stbs_20260926;
DELIMITER $$
CREATE PROCEDURE tcv_import_svn_stbs_20260926()
BEGIN
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 IF @import_stb_box_type IS NULL OR @import_stb_box_type NOT IN ('HD','SD') THEN
   SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Set @import_stb_box_type to HD or SD at the top of the file';
 END IF;
 START TRANSACTION;
 SELECT src.stb_number,@import_stb_box_type,'NEW',NULL,0,0,NULL,'NOT_AVAILABLE',CURDATE(),1
 FROM tmp_svn_stb_import src
 WHERE NOT EXISTS (
   SELECT 1 FROM cable_stb_master existing
   WHERE LOWER(TRIM(CONVERT(existing.stb_number USING utf8mb4))) COLLATE utf8mb4_unicode_ci = src.stb_number
 );
 SET @svn_stbs_inserted=ROW_COUNT();
 COMMIT;
END$$
DELIMITER ;
SET @svn_stbs_inserted=NULL;
CALL tcv_import_svn_stbs_20260926();
DROP PROCEDURE tcv_import_svn_stbs_20260926;
SELECT 900 AS spreadsheet_stbs,@svn_stbs_inserted AS inserted_stbs,
 900-@svn_stbs_inserted AS skipped_existing_stbs;
SELECT m.stb_master_id,m.stb_number,m.box_type,m.status,m.is_active
FROM cable_stb_master m JOIN tmp_svn_stb_import src
 ON LOWER(TRIM(CONVERT(m.stb_number USING utf8mb4))) COLLATE utf8mb4_unicode_ci=src.stb_number
ORDER BY m.stb_number,m.stb_master_id;
DROP TEMPORARY TABLE tmp_svn_stb_import;
